//==============================================================================
// FB_INST_ADM100W
// Trumeter ADM100W power meter, Modbus RTU, 32-bit float MSW first (ABCD). No command : local mode is only reported
// 1. INPUTS     : requests, control mode, command source, equipment feedback -> INTERN
// 2. PROCESSING : on INTERN only
// 3. OUTPUTS    : INTERN -> COM / IO / EXC
// Control mode  : local WEBVISU > local HMI > local FUXA > auto (functional units)
//==============================================================================

//------------------------------------------------------------------------------
// 1. INPUTS
//------------------------------------------------------------------------------
	//--- Control mode requests (WEBVISU, HMI, FUXA, global UPI)
	INTERN.FUXA_LOCAL_REQUEST := COM.SCADA_INPUT_LOCAL_REQUEST;
	INTERN.FUXA_AUTO_REQUEST  := COM.SCADA_INPUT_AUTO_REQUEST;
	INTERN.HMI_LOCAL_REQUEST  := COM.HMI_INPUT_LOCAL_REQUEST;
	INTERN.HMI_AUTO_REQUEST   := COM.HMI_INPUT_AUTO_REQUEST;
	INTERN.GLOBAL_LOCAL_FUXA  := EXC.UPI_INPUT_GLOBAL_LOCAL_FUXA;
	INTERN.GLOBAL_LOCAL_HMI   := EXC.UPI_INPUT_GLOBAL_LOCAL_HMI;
	INTERN.WEBVISU_LOCAL_REQUEST := COM.WEBVISU_INPUT_LOCAL_REQUEST;
	INTERN.WEBVISU_AUTO_REQUEST  := COM.WEBVISU_INPUT_AUTO_REQUEST;
	INTERN.GLOBAL_LOCAL_WEBVISU  := EXC.UPI_INPUT_GLOBAL_LOCAL_WEBVISU;

	//--- Control mode
	// Individual memories : set by the local request, reset by the auto request (auto wins if both)
	IF INTERN.WEBVISU_LOCAL_REQUEST THEN
		INTERN.LOCAL_WEBVISU_INDIVIDUAL := TRUE;
	END_IF
	IF INTERN.WEBVISU_AUTO_REQUEST THEN
		INTERN.LOCAL_WEBVISU_INDIVIDUAL := FALSE;
	END_IF
	IF INTERN.HMI_LOCAL_REQUEST THEN
		INTERN.LOCAL_HMI_INDIVIDUAL := TRUE;
	END_IF
	IF INTERN.HMI_AUTO_REQUEST THEN
		INTERN.LOCAL_HMI_INDIVIDUAL := FALSE;
	END_IF
	IF INTERN.FUXA_LOCAL_REQUEST THEN
		INTERN.LOCAL_FUXA_INDIVIDUAL := TRUE;
	END_IF
	IF INTERN.FUXA_AUTO_REQUEST THEN
		INTERN.LOCAL_FUXA_INDIVIDUAL := FALSE;
	END_IF

	// Resulting mode : individual OR global, WEBVISU > HMI > FUXA > auto
	INTERN.LOCAL_WEBVISU := INTERN.LOCAL_WEBVISU_INDIVIDUAL OR INTERN.GLOBAL_LOCAL_WEBVISU;
	INTERN.LOCAL_HMI     := (INTERN.LOCAL_HMI_INDIVIDUAL OR INTERN.GLOBAL_LOCAL_HMI) AND NOT INTERN.LOCAL_WEBVISU;
	INTERN.LOCAL_FUXA    := (INTERN.LOCAL_FUXA_INDIVIDUAL OR INTERN.GLOBAL_LOCAL_FUXA) AND NOT INTERN.LOCAL_WEBVISU AND NOT INTERN.LOCAL_HMI;
	INTERN.AUTO          := NOT INTERN.LOCAL_WEBVISU AND NOT INTERN.LOCAL_HMI AND NOT INTERN.LOCAL_FUXA;

	//--- COM : alarms (coils 0..9)
	INTERN.ALARM_1  := COM.COM_INPUT_COILS[0].0;
	INTERN.ALARM_2  := COM.COM_INPUT_COILS[0].1;
	INTERN.ALARM_3  := COM.COM_INPUT_COILS[0].2;
	INTERN.ALARM_4  := COM.COM_INPUT_COILS[0].3;
	INTERN.ALARM_5  := COM.COM_INPUT_COILS[0].4;
	INTERN.ALARM_6  := COM.COM_INPUT_COILS[0].5;
	INTERN.ALARM_7  := COM.COM_INPUT_COILS[0].6;
	INTERN.ALARM_8  := COM.COM_INPUT_COILS[0].7;
	INTERN.ALARM_9  := COM.COM_INPUT_COILS[1].0;
	INTERN.ALARM_10 := COM.COM_INPUT_COILS[1].1;

	//--- COM : measures (input registers, MSW first)
	INTERN.FREQUENCY                 := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[0], Low_word := COM.COM_INPUT_IR[1]);
	INTERN.L1_L2_VOLTAGE             := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[2], Low_word := COM.COM_INPUT_IR[3]);
	INTERN.L1_N_VOLTAGE              := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[4], Low_word := COM.COM_INPUT_IR[5]);
	INTERN.L1_CURRENT                := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[6], Low_word := COM.COM_INPUT_IR[7]);
	INTERN.L1_ACTIVE_POWER           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[8], Low_word := COM.COM_INPUT_IR[9]);
	INTERN.L1_APPARENT_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[10], Low_word := COM.COM_INPUT_IR[11]);
	INTERN.L1_REACTIVE_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[12], Low_word := COM.COM_INPUT_IR[13]);
	INTERN.L1_CURRENT_PHASE_ANGLE    := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[14], Low_word := COM.COM_INPUT_IR[15]);
	INTERN.L1_POWER_FACTOR           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[16], Low_word := COM.COM_INPUT_IR[17]);
	INTERN.L1_VOLTAGE_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[18], Low_word := COM.COM_INPUT_IR[19]);
	INTERN.L1_CURRENT_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[20], Low_word := COM.COM_INPUT_IR[21]);
	INTERN.L1_MAX_LOAD               := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[22], Low_word := COM.COM_INPUT_IR[23]);
	INTERN.L1_L2_VOLTAGE_PHASE_ANGLE := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[24], Low_word := COM.COM_INPUT_IR[25]);
	INTERN.L2_L3_VOLTAGE             := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[26], Low_word := COM.COM_INPUT_IR[27]);
	INTERN.L2_N_VOLTAGE              := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[28], Low_word := COM.COM_INPUT_IR[29]);
	INTERN.L2_CURRENT                := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[30], Low_word := COM.COM_INPUT_IR[31]);
	INTERN.L2_ACTIVE_POWER           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[32], Low_word := COM.COM_INPUT_IR[33]);
	INTERN.L2_APPARENT_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[34], Low_word := COM.COM_INPUT_IR[35]);
	INTERN.L2_REACTIVE_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[36], Low_word := COM.COM_INPUT_IR[37]);
	INTERN.L2_CURRENT_PHASE_ANGLE    := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[38], Low_word := COM.COM_INPUT_IR[39]);
	INTERN.L2_POWER_FACTOR           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[40], Low_word := COM.COM_INPUT_IR[41]);
	INTERN.L2_VOLTAGE_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[42], Low_word := COM.COM_INPUT_IR[43]);
	INTERN.L2_CURRENT_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[44], Low_word := COM.COM_INPUT_IR[45]);
	INTERN.L2_MAX_LOAD               := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[46], Low_word := COM.COM_INPUT_IR[47]);
	INTERN.L1_L3_VOLTAGE_PHASE_ANGLE := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[48], Low_word := COM.COM_INPUT_IR[49]);
	INTERN.L3_L1_VOLTAGE             := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[50], Low_word := COM.COM_INPUT_IR[51]);
	INTERN.L3_N_VOLTAGE              := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[52], Low_word := COM.COM_INPUT_IR[53]);
	INTERN.L3_CURRENT                := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[54], Low_word := COM.COM_INPUT_IR[55]);
	INTERN.L3_ACTIVE_POWER           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[56], Low_word := COM.COM_INPUT_IR[57]);
	INTERN.L3_APPARENT_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[58], Low_word := COM.COM_INPUT_IR[59]);
	INTERN.L3_REACTIVE_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[60], Low_word := COM.COM_INPUT_IR[61]);
	INTERN.L3_CURRENT_PHASE_ANGLE    := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[62], Low_word := COM.COM_INPUT_IR[63]);
	INTERN.L3_POWER_FACTOR           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[64], Low_word := COM.COM_INPUT_IR[65]);
	INTERN.L3_VOLTAGE_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[66], Low_word := COM.COM_INPUT_IR[67]);
	INTERN.L3_CURRENT_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[68], Low_word := COM.COM_INPUT_IR[69]);
	INTERN.L3_MAX_LOAD               := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[70], Low_word := COM.COM_INPUT_IR[71]);
	INTERN.INTERNAL_TEMPERATURE      := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[72], Low_word := COM.COM_INPUT_IR[73]);
	INTERN.ACTIVE_ENERGY             := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[74], Low_word := COM.COM_INPUT_IR[75]);
	INTERN.APPARENT_ENERGY           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[76], Low_word := COM.COM_INPUT_IR[77]);
	INTERN.REACTIVE_ENERGY           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[78], Low_word := COM.COM_INPUT_IR[79]);
	INTERN.TOTAL_ACTIVE_POWER        := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[80], Low_word := COM.COM_INPUT_IR[81]);
	INTERN.TOTAL_APPARENT_POWER      := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[82], Low_word := COM.COM_INPUT_IR[83]);
	INTERN.TOTAL_REACTIVE_POWER      := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[84], Low_word := COM.COM_INPUT_IR[85]);
	INTERN.ALL_PHASE_POWER_FACTOR    := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[86], Low_word := COM.COM_INPUT_IR[87]);


//------------------------------------------------------------------------------
// 2. PROCESSING
//------------------------------------------------------------------------------
	// Nothing


//------------------------------------------------------------------------------
// 3. OUTPUTS
//------------------------------------------------------------------------------
	//--- COM : control mode status to SCADA, HMI and WEBVISU
	COM.SCADA_OUTPUT_LOCAL_FUXA_ACTIVE := INTERN.LOCAL_FUXA;
	COM.SCADA_OUTPUT_LOCAL_HMI_ACTIVE  := INTERN.LOCAL_HMI;
	COM.HMI_OUTPUT_LOCAL_ACTIVE        := INTERN.LOCAL_HMI;
	COM.WEBVISU_OUTPUT_LOCAL_ACTIVE        := INTERN.LOCAL_WEBVISU;
	COM.WEBVISU_OUTPUT_LOCAL_HMI_ACTIVE  := INTERN.LOCAL_HMI;
	COM.WEBVISU_OUTPUT_LOCAL_FUXA_ACTIVE := INTERN.LOCAL_FUXA;

	//--- EXC
	EXC.EXC_OUTPUT_FREQUENCY            := INTERN.FREQUENCY;
	EXC.EXC_OUTPUT_L1_N_VOLTAGE         := INTERN.L1_N_VOLTAGE;
	EXC.EXC_OUTPUT_L1_CURRENT           := INTERN.L1_CURRENT;
	EXC.EXC_OUTPUT_L1_ACTIVE_POWER      := INTERN.L1_ACTIVE_POWER;
	EXC.EXC_OUTPUT_L1_APPARENT_POWER    := INTERN.L1_APPARENT_POWER;
	EXC.EXC_OUTPUT_L1_REACTIVE_POWER    := INTERN.L1_REACTIVE_POWER;
	EXC.EXC_OUTPUT_L1_POWER_FACTOR      := INTERN.L1_POWER_FACTOR;
	EXC.EXC_OUTPUT_L1_VOLTAGE_THD       := INTERN.L1_VOLTAGE_THD;
	EXC.EXC_OUTPUT_L1_CURRENT_THD       := INTERN.L1_CURRENT_THD;
	EXC.EXC_OUTPUT_L1_MAX_LOAD          := INTERN.L1_MAX_LOAD;
	EXC.EXC_OUTPUT_INTERNAL_TEMPERATURE := INTERN.INTERNAL_TEMPERATURE;
	EXC.EXC_OUTPUT_ACTIVE_ENERGY        := INTERN.ACTIVE_ENERGY;
	// EXC.EXC_OUTPUT_DATA_VALID : not managed yet (no Modbus diagnostic)

	//--- COM : alarms to SCADA, HMI and WEBVISU
	COM.SCADA_OUTPUT_ALARM_1_STATUS  := INTERN.ALARM_1;
	COM.HMI_OUTPUT_ALARM_1_STATUS    := INTERN.ALARM_1;
	COM.WEBVISU_OUTPUT_ALARM_1_STATUS    := INTERN.ALARM_1;
	COM.SCADA_OUTPUT_ALARM_2_STATUS  := INTERN.ALARM_2;
	COM.HMI_OUTPUT_ALARM_2_STATUS    := INTERN.ALARM_2;
	COM.WEBVISU_OUTPUT_ALARM_2_STATUS    := INTERN.ALARM_2;
