	COM.HMI_OUTPUT_ALARM_3_STATUS    := INTERN.ALARM_3;
	COM.WEBVISU_OUTPUT_ALARM_3_STATUS    := INTERN.ALARM_3;
	COM.SCADA_OUTPUT_ALARM_4_STATUS  := INTERN.ALARM_4;
	COM.HMI_OUTPUT_ALARM_4_STATUS    := INTERN.ALARM_4;
	COM.WEBVISU_OUTPUT_ALARM_4_STATUS    := INTERN.ALARM_4;
	COM.SCADA_OUTPUT_ALARM_5_STATUS  := INTERN.ALARM_5;
	COM.HMI_OUTPUT_ALARM_5_STATUS    := INTERN.ALARM_5;
	COM.WEBVISU_OUTPUT_ALARM_5_STATUS    := INTERN.ALARM_5;
	COM.SCADA_OUTPUT_ALARM_6_STATUS  := INTERN.ALARM_6;
