	COM.SCADA_OUTPUT_ALARM_7_STATUS  := INTERN.ALARM_7;
	COM.HMI_OUTPUT_ALARM_7_STATUS    := INTERN.ALARM_7;
	COM.WEBVISU_OUTPUT_ALARM_7_STATUS    := INTERN.ALARM_7;
	COM.SCADA_OUTPUT_ALARM_8_STATUS  := INTERN.ALARM_8;
	COM.HMI_OUTPUT_ALARM_8_STATUS    := INTERN.ALARM_8;
